from math import sqrt as root
import statistics as stats

def report(values):
    return stats.mean(values), root(sum(values))

assert report([4, 5]) == (4.5, 3.0)

def read_count(text: str) -> int:
    try:
        count = int(text)
    except ValueError as error:
        raise ValueError("count must be an integer") from error
    if count < 0:
        raise ValueError("count must be nonnegative")
    return count

assert read_count("3") == 3
try:
    read_count("bad")
except ValueError as error:
    assert isinstance(error.__cause__, ValueError)
else:
    raise AssertionError("expected invalid count")

class Basket:
    def __init__(self):
        self.items = []

    def add(self, item):
        self.items.append(item)

first, second = Basket(), Basket()
first.add("apple")
assert first.items == ["apple"]
assert second.items == []

def positive_squares(values):
    for value in values:
        if value > 0:
            yield value * value

result = positive_squares([-1, 2, 3])
assert next(result) == 4
assert list(result) == [9]
assert list(result) == []

from contextlib import contextmanager

events = []
@contextmanager
def session():
    events.append("open")
    try:
        yield "resource"
    finally:
        events.append("close")

try:
    with session() as resource:
        assert resource == "resource"
        raise ValueError("failed work")
except ValueError:
    pass
assert events == ["open", "close"]

import json

payload = {"name": "Ada", "active": True}
