import httpx

def respond(request):
    assert request.url.params["page"] == "1"
    return httpx.Response(200, json={"items": ["tea"]})

with httpx.Client(transport=httpx.MockTransport(respond), timeout=httpx.Timeout(5.0)) as client:
    try:
        response = client.get("https://example.test/items", params={"page": 1})
        response.raise_for_status()
        items = response.json()["items"]
    except httpx.HTTPError as error:
        raise RuntimeError("request failed") from error
assert items == ["tea"]

from pydantic import BaseModel, Field, ValidationError

class Order(BaseModel):
    name: str
    quantity: int = Field(gt=0)

order = Order.model_validate({"name": "tea", "quantity": 3}, strict=True)
assert order.model_dump() == {"name": "tea", "quantity": 3}
try:
    Order.model_validate({"name": "tea", "quantity": 0})
except ValidationError as error:
    assert error.errors()[0]["loc"] == ("quantity",)
else:
    raise AssertionError("expected invalid quantity")

import httpx

def respond(request):
    if request.url.path == "/slow":
        raise httpx.ReadTimeout("read timed out", request=request)
    return httpx.Response(503)

with httpx.Client(transport=httpx.MockTransport(respond), timeout=0.1) as client:
    try:
        client.get("https://example.test/slow")
    except httpx.TimeoutException:
        timeout_handled = True
    else:
        timeout_handled = False
    try:
        client.get("https://example.test/unavailable").raise_for_status()
    except httpx.HTTPStatusError as error:
        assert error.response.status_code == 503
    else:
        raise AssertionError("expected HTTP failure")
assert timeout_handled
